// global-config.mjs -- reads fgOS's global config file (~/.fgos/config.json)
// and merges it with a project config, project always winning
// (docs/history/global-project-config-awareness/CONTEXT.md D1).
//
// config-merge.mjs's own header comment already anticipated this exact
// caller ("a future caller may be a user-level config file") -- this module
// is that caller: mergeConfigDefaults(existing, defaults) already gives
// "existing wins, defaults only fill gaps" semantics, which is exactly
// "project overwrites global" when existing=project, defaults=global.

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import { mergeConfigDefaults } from '../setup/config-merge.mjs';
import { sharedConfigFilePath } from './shared-config-file.mjs';

// A function, not a module-load-time const: os.homedir() must be read fresh
// on every call, not frozen the first time this module is imported --
// otherwise a caller overriding process.env.HOME (tests; anything else that
// legitimately runs with a different HOME) after this module already
// loaded would see the wrong, stale path. `GLOBAL_CONFIG_PATH` below is
// still exported as a snapshot for display purposes (messages, docs), but
// every function's own default resolution calls this, never the constant.
function defaultGlobalConfigPath() {
  return path.join(os.homedir(), '.fgos', 'config.json');
}

export const GLOBAL_CONFIG_PATH = defaultGlobalConfigPath();

/**
 * Read+parse the global config file. A missing file is not an error --
 * global config is optional -- and resolves to `{}`. A present-but-invalid
 * file throws, the same discipline dispatch.mjs's loadRunnerConfig already
 * applies to the project-level file.
 */
export function loadGlobalConfig(globalConfigPath = defaultGlobalConfigPath()) {
  if (!fs.existsSync(globalConfigPath)) return {};
  const raw = fs.readFileSync(globalConfigPath, 'utf8');
  try {
    return JSON.parse(raw);
  } catch (err) {
    throw new Error(`cannot parse global config at "${globalConfigPath}": ${err.message}`);
  }
}

/**
 * `projectConfig` merged with the global config, project winning any key
 * present in both.
 *
 * `sanitizeGlobal`, when given, runs on the loaded global config before the
 * merge — a caller-supplied, schema-aware filter for a global config file
 * this module itself has no schema knowledge of (kept general-purpose per
 * this file's header comment). Its purpose: a global config value that is
 * no longer valid against the current schema (e.g. a tier name retired by a
 * later migration) must never be allowed to fill a gap in a project config
 * that is missing that same key. `mergeConfigDefaults`'s fill-missing-only
 * contract has no way to know a key is stale rather than a legitimate
 * project-level customization, so the caller filters before merging, not
 * after: a stale key left in place would silently propagate into every
 * project's merged config and, once validation rejects the unknown key,
 * break every config load on that machine rather than just one project.
 */
export function mergeWithGlobalConfig(projectConfig, globalConfigPath = defaultGlobalConfigPath(), { sanitizeGlobal } = {}) {
  const rawGlobalConfig = loadGlobalConfig(globalConfigPath);
  const globalConfig = sanitizeGlobal ? sanitizeGlobal(rawGlobalConfig) : rawGlobalConfig;
  return mergeConfigDefaults(projectConfig ?? {}, globalConfig).merged;
}

/**
 * Write `config` to the global config file, creating `~/.fgos/` if needed
 * (tsk-2qc-1 D4 — the write half `loadGlobalConfig` never had: this file
 * used to be read-only, since nothing needed to persist anything into it
 * before the tier-3 bin-discovery cache). Same "the only write path in
 * this module, callers decide WHEN to write" discipline
 * `writeSharedConfig` already applies to the project-level file.
 */
export function writeGlobalConfig(config, globalConfigPath = defaultGlobalConfigPath()) {
  fs.mkdirSync(path.dirname(globalConfigPath), { recursive: true });
  fs.writeFileSync(globalConfigPath, `${JSON.stringify(config, null, 2)}\n`);
}

/**
 * Which config level is active for `cwd`'s project (project config wins
 * when present, per D1), and whether the other level is also present --
 * the awareness data `fgos doctor`'s config-awareness check reports on.
 *
 * `projectPresent` reflects the shared file (`.fgos/config.json`) alone
 * (tsk-5hv D1: the legacy runner config file was retired, no fallback).
 */
export function describeConfigAwareness(cwd, { globalConfigPath = defaultGlobalConfigPath(), projectConfigPath } = {}) {
  const resolvedProjectPath = projectConfigPath ?? sharedConfigFilePath(cwd);
  const globalPresent = fs.existsSync(globalConfigPath);
  const projectPresent = fs.existsSync(resolvedProjectPath);
  const active = projectPresent ? 'project' : globalPresent ? 'global' : 'none';
  return {
    active,
    globalPresent,
    projectPresent,
    globalConfigPath,
    projectConfigPath: resolvedProjectPath,
  };
}

// shared-config-file.mjs -- the shared project config file (`.fgos/config.json`,
// tsk-2ta D1 amended / tsk-5vf D1): one JSON file, one top-level section per
// module (each module's own `registerConfigDefault` `key`, tsk-2cs D3/D6).
// The legacy runner config file was retired (tsk-5hv D1) -- this is now
// the sole config source, no fallback. `fgos setup` is what performs the real
// write (D2); this module never writes on its own from a read (RUL9's
// doctor-never-writes discipline, extended here to every read-only caller
// of this module).
//
// `dir` is whatever project root the caller already resolved (repoRoot for
// the runner path, cwd for doctor checks) -- no extra main-checkout
// indirection. This file is NOT in `.gitignore`, so it is a normal
// git-tracked file: every worktree checkout carries its own copy via
// ordinary `git checkout`.

import fs from 'node:fs';
import path from 'node:path';

export function sharedConfigFilePath(dir) {
  return path.join(dir, '.fgos', 'config.json');
}

/**
 * Read the shared config file at `dir`. Returns `{}` when it doesn't
 * exist. Invalid JSON throws, matching `loadGlobalConfig`'s existing
 * discipline.
 */
export function readSharedConfig(dir) {
  const sharedPath = sharedConfigFilePath(dir);
  if (fs.existsSync(sharedPath)) {
    const raw = fs.readFileSync(sharedPath, 'utf8');
    try {
      return JSON.parse(raw);
    } catch (err) {
      throw new Error(`cannot parse shared config at "${sharedPath}": ${err.message}`);
    }
  }
  return {};
}

// The repo-invariant check commands: deterministic, pure-read checks whose
// pass/fail never depends on which item is being worked. They run alongside
// an item's own `verify` at `return` and post-merge, so a repo-wide
// invariant broken by item A cannot land on main unnoticed and stay red
// across later merges (docs/history/tsk-516-approve-reverify-scope/
// CONTEXT.md D2/D3/D4).
//
// Declared here, in the config layer, rather than hardcoded in the runner:
// fgOS is a platform, and a project using it has its own invariant command,
// not this repo's test layout (D6). This constant is only the default that
// `fgos setup` writes -- the runner reads whatever the project's own config
// actually says, and an absent section means no invariant check runs at all,
// leaving behavior identical to before this existed.
//
// Lives in this domain-layer module (not next to its `registerConfigDefault`
// call in the use-case layer) so both the use-case registration and the
// infra-layer runner import it DOWNWARD -- an infra->use-case import would
// break the one-way-down rule test/architecture.test.mjs enforces, which is
// the very invariant this feature exists to protect.
export const DEFAULT_INVARIANT_CHECK_COMMANDS = ['node --test test/architecture.test.mjs'];

/**
 * The invariant-check commands configured at `dir`, as a list of real
 * command strings. Returns `[]` for every shape that isn't a genuine list
 * of non-empty strings -- an absent section, a malformed one, or a list
 * with nothing runnable in it. Never falls back to
 * `DEFAULT_INVARIANT_CHECK_COMMANDS`: that default belongs to what `fgos
 * setup` WRITES, never to what a reader silently assumes -- otherwise a
 * project that deliberately configured no invariant checks would still get
 * this repo's own test command imposed on it.
 */
export function readInvariantCheckCommands(dir) {
  const section = readSharedConfig(dir).invariantChecks;
  if (!section || typeof section !== 'object' || Array.isArray(section)) return [];
  if (!Array.isArray(section.commands)) return [];
  return section.commands.filter((command) => typeof command === 'string' && command.trim() !== '');
}

// Project-specific commands every runner-created worktree runs after its
// dependency install, before anything verifies in it -- e.g. building a
// compiled binary the test suite needs, which a fresh checkout never has
// (git only checks out tracked files). Empty by default: a project that
// declares nothing keeps exactly today's behavior.
export const DEFAULT_WORKTREE_SETUP_COMMANDS = [];

/**
 * The worktree setup commands configured at `dir` (`worktreeSetup.commands`),
 * as a list of non-empty command strings. `[]` for an absent or malformed
 * section -- same never-assume-a-default discipline as
 * `readInvariantCheckCommands`.
 */
export function readWorktreeSetupCommands(dir) {
  const section = readSharedConfig(dir).worktreeSetup;
  if (!section || typeof section !== 'object' || Array.isArray(section)) return [];
  if (!Array.isArray(section.commands)) return [];
  return section.commands.filter((command) => typeof command === 'string' && command.trim() !== '');
}

/**
 * Write `config` to the shared config file at `dir`, creating `.fgos/` if
 * needed. The only write path in this module -- callers decide WHEN to
 * write (`fgos setup`'s bootstrap, or the runner's own first-run default),
 * never triggered implicitly by a read.
 */
export function writeSharedConfig(dir, config) {
  const sharedPath = sharedConfigFilePath(dir);
  fs.mkdirSync(path.dirname(sharedPath), { recursive: true });
  fs.writeFileSync(sharedPath, `${JSON.stringify(config, null, 2)}\n`);
}

/**
 * `readSharedConfig` that degrades to `{}` instead of throwing on a file that
 * is present but not valid JSON.
 *
 * The shared config is explicitly an edit-the-file-by-hand surface, so a
 * half-typed edit is an ordinary state, not an exceptional one. A reader that
 * only wants one optional setting should behave the way it behaves when the
 * setting is absent — `readGateBypassLevel` has wrapped this call in exactly
 * this try/catch since it was written, for exactly this reason.
 *
 * Use this for an OPTIONAL setting whose absence is already meaningful. Do NOT
 * use it where the caller's whole job is to report on the file's health:
 * `fgos doctor`'s own checks must see the parse failure, not a tidy empty
 * object, or the one command that exists to name the problem would hide it.
 */
export function readSharedConfigOrEmpty(dir) {
  try {
    return readSharedConfig(dir);
  } catch {
    return {};
  }
}
